describe('Active Sessions Management', () => {
  beforeEach(() => {
    cy.visit('/user-profile');
  });

  it('should display all active sessions and log out a specific one', () => {
    // Verify initial active sessions are displayed
    cy.get('[data-testid="active-sessions-list"]').should('be.visible');
    cy.get('[data-testid="session-item"]').should('have.length.greaterThan', 0);

    // Verify session details are visible
    cy.get('[data-testid="session-item"]').first().should('be.visible');
    cy.get('[data-testid="session-name"]').first().should('contain', 'Session 1');
    cy.get('[data-testid="session-status"]').first().should('contain', 'Active');

    // Verify logout button is present
    cy.get('[data-testid="logout-button"]').should('be.visible');

    // Click logout button for a specific session
    cy.get('[data-testid="session-item"]').first().within(() => {
      cy.get('[data-testid="logout-button"]').click();
    });

    // Verify session is removed from the list
    cy.get('[data-testid="active-sessions-list"]').should('contain', 'Session 1');
    cy.get('[data-testid="session-item"]').first().should('not.exist');

    // Verify remaining sessions are still displayed
    cy.get('[data-testid="session-item"]').should('have.length.greaterThan', 0);

    // Verify logout was successful
    cy.get('[data-testid="success-message"]').should('be.visible');
    cy.get('[data-testid="success-message"]').should('contain', 'Session 1 logged out successfully');
  });

  it('should handle edge case: logout button disabled for inactive sessions', () => {
    // Verify initial active sessions are displayed
    cy.get('[data-testid="active-sessions-list"]').should('be.visible');

    // Verify logout button is disabled for inactive sessions
    cy.get('[data-testid="session-item"]').first().within(() => {
      cy.get('[data-testid="logout-button"]').should('be.disabled');
      cy.get('[data-testid="logout-button"]').should('have.attr', 'aria-disabled', 'true');
    });

    // Verify logout button is enabled for active sessions
    cy.get('[data-testid="session-item"]').first().within(() => {
      cy.get('[data-testid="logout-button"]').should('not.be.disabled');
    });

    // Verify success message is not shown for inactive sessions
    cy.get('[data-testid="success-message"]').should('not.exist');
  });
});
